/** Domain-neutral field validation. Rules are plain functions, composable per field. */

export type FieldRule<Value> = (value: Value) => string | undefined;
export type FieldErrors<Fields> = Partial<Record<keyof Fields, string>>;

export function required(message = "This field is required"): FieldRule<string> {
  return (value) => (value.trim() === "" ? message : undefined);
}

export function minLength(length: number, message?: string): FieldRule<string> {
  return (value) =>
    value.trim().length < length ? (message ?? `Use at least ${length} characters`) : undefined;
}

export function maxLength(length: number, message?: string): FieldRule<string> {
  return (value) =>
    value.trim().length > length ? (message ?? `Use at most ${length} characters`) : undefined;
}

export function pattern(expression: RegExp, message: string): FieldRule<string> {
  return (value) => (value.trim() === "" || expression.test(value.trim()) ? undefined : message);
}

export function isNumber(message = "Enter a number"): FieldRule<string> {
  return (value) => (value.trim() !== "" && Number.isNaN(Number(value)) ? message : undefined);
}

export function numberRange(min: number, max: number, message?: string): FieldRule<string> {
  return (value) => {
    if (value.trim() === "") return undefined;
    const parsed = Number(value);
    if (Number.isNaN(parsed)) return message ?? "Enter a number";
    return parsed < min || parsed > max ? (message ?? `Enter a value between ${min} and ${max}`) : undefined;
  };
}

export function oneOf(allowed: readonly string[], message = "Choose one of the options"): FieldRule<string> {
  return (value) => (allowed.includes(value) ? undefined : message);
}

/** Fails when another record already uses the same normalized value. */
export function unique(existing: readonly string[], message = "This already exists"): FieldRule<string> {
  const taken = new Set(existing.map((entry) => entry.trim().replaceAll(/\s+/gu, " ").toLowerCase()));
  return (value) => (taken.has(value.trim().replaceAll(/\s+/gu, " ").toLowerCase()) ? message : undefined);
}

export function firstError<Value>(value: Value, rules: readonly FieldRule<Value>[]): string | undefined {
  for (const rule of rules) {
    const error = rule(value);
    if (error) return error;
  }
  return undefined;
}

/** Runs every field's rules and returns only the fields that failed. */
export function validateFields<Fields extends Record<string, string>>(
  values: Fields,
  rules: { [Key in keyof Fields]?: readonly FieldRule<string>[] },
): FieldErrors<Fields> {
  const errors: FieldErrors<Fields> = {};
  for (const key of Object.keys(values) as (keyof Fields)[]) {
    const fieldRules = rules[key];
    if (!fieldRules) continue;
    const error = firstError(values[key], fieldRules);
    if (error) errors[key] = error;
  }
  return errors;
}

export function hasErrors<Fields>(errors: FieldErrors<Fields>): boolean {
  return Object.values(errors).some((entry) => typeof entry === "string" && entry !== "");
}

/**
 * Versioned, corruption-tolerant browser storage.
 *
 * Every document is stored as { version, records }. Unreadable, non-JSON, wrong-shaped,
 * or partially invalid data never throws: the loader reports what it recovered so the UI
 * can tell the user, and the app keeps working with the records that survived.
 */

export interface StoredDocument<Record_> {
  version: number;
  records: Record_[];
}

export type StorageStatus = "ok" | "empty" | "recovered" | "unavailable";

export interface LoadOutcome<Record_> {
  records: Record_[];
  status: StorageStatus;
  /** Human readable reason, present when status is "recovered" or "unavailable". */
  message?: string;
}

export interface StorageOptions<Record_> {
  version?: number;
  /** Returns the record when it is usable, otherwise undefined so it is dropped. */
  parseRecord: (value: unknown) => Record_ | undefined;
  /** Upgrades a document written by an older version of the app. */
  migrate?: (records: unknown[], fromVersion: number) => unknown[];
}

export interface Storage_<Record_> {
  key: string;
  version: number;
  load: () => LoadOutcome<Record_>;
  save: (records: Record_[]) => { saved: boolean; message?: string };
  clear: () => void;
}

function backend(): globalThis.Storage | undefined {
  try {
    const candidate = globalThis.localStorage;
    if (!candidate) return undefined;
    const probe = "__storage_probe__";
    candidate.setItem(probe, "1");
    candidate.removeItem(probe);
    return candidate;
  } catch {
    return undefined;
  }
}

export function safeJsonParse(raw: string): { ok: true; value: unknown } | { ok: false } {
  try {
    return { ok: true, value: JSON.parse(raw) as unknown };
  } catch {
    return { ok: false };
  }
}

export function createStorage<Record_>(key: string, options: StorageOptions<Record_>): Storage_<Record_> {
  const version = options.version ?? 1;

  function load(): LoadOutcome<Record_> {
    const store = backend();
    if (!store) {
      return { records: [], status: "unavailable", message: "Browser storage is unavailable; changes will not be saved." };
    }

    let raw: string | null = null;
    try {
      raw = store.getItem(key);
    } catch {
      return { records: [], status: "unavailable", message: "Saved data could not be read." };
    }
    if (raw === null || raw.trim() === "") return { records: [], status: "empty" };

    const parsed = safeJsonParse(raw);
    if (!parsed.ok) {
      return { records: [], status: "recovered", message: "Saved data was unreadable and has been reset." };
    }

    const document_ = parsed.value as Partial<StoredDocument<unknown>> | unknown[];
    const isArray = Array.isArray(document_);
    const storedVersion = isArray ? 0 : Number((document_ as StoredDocument<unknown>).version ?? 0);
    const rawRecords: unknown = isArray ? document_ : (document_ as StoredDocument<unknown>).records;
    if (!Array.isArray(rawRecords)) {
      return { records: [], status: "recovered", message: "Saved data had an unexpected shape and has been reset." };
    }

    const upgraded =
      storedVersion !== version && options.migrate ? options.migrate(rawRecords, storedVersion) : rawRecords;
    const records: Record_[] = [];
    let dropped = 0;
    for (const entry of Array.isArray(upgraded) ? upgraded : []) {
      const record = options.parseRecord(entry);
      if (record === undefined) dropped += 1;
      else records.push(record);
    }

    if (dropped > 0) {
      return {
        records,
        status: "recovered",
        message: `${dropped} damaged ${dropped === 1 ? "entry was" : "entries were"} skipped while loading saved data.`,
      };
    }
    if (storedVersion !== version) {
      return { records, status: "recovered", message: "Saved data was upgraded to the current format." };
    }
    return { records, status: records.length === 0 ? "empty" : "ok" };
  }

  function save(records: Record_[]): { saved: boolean; message?: string } {
    const store = backend();
    if (!store) return { saved: false, message: "Browser storage is unavailable; changes will not be saved." };
    try {
      const document_: StoredDocument<Record_> = { version, records };
      store.setItem(key, JSON.stringify(document_));
      return { saved: true };
    } catch {
      return { saved: false, message: "Changes could not be saved; storage is full or blocked." };
    }
  }

  function clear(): void {
    try {
      backend()?.removeItem(key);
    } catch {
      // Clearing is best effort; the in-memory state stays authoritative.
    }
  }

  return { key, version, load, save, clear };
}

/**
 * React binding for a repository: loads once, keeps records in state, persists on change
 * and surfaces storage problems as a user-visible notice instead of a crash.
 */
import { useCallback, useEffect, useMemo, useState } from "react";
import type { Entity, Repository } from "../lib/repository.js";
import type { StorageStatus } from "../lib/storage.js";

export interface CollectionState<Record_ extends Entity> {
  records: Record_[];
  loading: boolean;
  status: StorageStatus;
  notice?: string;
  create: (input: Omit<Record_, keyof Entity>) => Record_;
  update: (id: string, changes: Partial<Omit<Record_, keyof Entity>>) => void;
  remove: (id: string) => void;
  replaceAll: (records: Record_[]) => void;
  dismissNotice: () => void;
}

export function useCollection<Record_ extends Entity>(
  repository: Repository<Record_>,
): CollectionState<Record_> {
  const [records, setRecords] = useState<Record_[]>([]);
  const [loading, setLoading] = useState(true);
  const [status, setStatus] = useState<StorageStatus>("empty");
  const [notice, setNotice] = useState<string | undefined>(undefined);

  useEffect(() => {
    const outcome = repository.load();
    setRecords(outcome.records);
    setStatus(outcome.status);
    setNotice(outcome.message);
    setLoading(false);
  }, [repository]);

  const commit = useCallback(
    (next: Record_[]) => {
      setRecords(next);
      const saved = repository.save(next);
      if (!saved.saved) {
        setStatus("unavailable");
        setNotice(saved.message);
      }
    },
    [repository],
  );

  const create = useCallback(
    (input: Omit<Record_, keyof Entity>) => {
      const created = repository.create(records, input);
      commit(created.records);
      return created.record;
    },
    [commit, records, repository],
  );

  const update = useCallback(
    (id: string, changes: Partial<Omit<Record_, keyof Entity>>) => {
      commit(repository.update(records, id, changes));
    },
    [commit, records, repository],
  );

  const remove = useCallback(
    (id: string) => {
      commit(repository.remove(records, id));
    },
    [commit, records, repository],
  );

  const replaceAll = useCallback(
    (next: Record_[]) => {
      commit(repository.replaceAll(next));
    },
    [commit, repository],
  );

  return useMemo(
    () => ({
      records,
      loading,
      status,
      ...(notice === undefined ? {} : { notice }),
      create,
      update,
      remove,
      replaceAll,
      dismissNotice: () => setNotice(undefined),
    }),
    [create, loading, notice, records, remove, replaceAll, status, update],
  );
}

/** Query helpers for in-memory collections: search, filter, sort, group, count. */

export function searchRecords<Record_>(
  records: readonly Record_[],
  query: string,
  fields: readonly ((record: Record_) => string | undefined)[],
): Record_[] {
  const needle = query.trim().toLowerCase();
  if (needle === "") return [...records];
  return records.filter((record) =>
    fields.some((read) => (read(record) ?? "").toLowerCase().includes(needle)),
  );
}

export function filterRecords<Record_>(
  records: readonly Record_[],
  predicates: readonly ((record: Record_) => boolean)[],
): Record_[] {
  return records.filter((record) => predicates.every((predicate) => predicate(record)));
}

export function sortRecords<Record_>(
  records: readonly Record_[],
  read: (record: Record_) => string | number,
  direction: "asc" | "desc" = "asc",
): Record_[] {
  const factor = direction === "asc" ? 1 : -1;
  return [...records].sort((a, b) => {
    const left = read(a);
    const right = read(b);
    if (typeof left === "number" && typeof right === "number") return (left - right) * factor;
    return String(left).localeCompare(String(right)) * factor;
  });
}

export function groupRecords<Record_>(
  records: readonly Record_[],
  read: (record: Record_) => string,
): Map<string, Record_[]> {
  const groups = new Map<string, Record_[]>();
  for (const record of records) {
    const key = read(record);
    const bucket = groups.get(key);
    if (bucket) bucket.push(record);
    else groups.set(key, [record]);
  }
  return groups;
}

export function countBy<Record_>(
  records: readonly Record_[],
  predicate: (record: Record_) => boolean,
): number {
  return records.reduce((total, record) => (predicate(record) ? total + 1 : total), 0);
}

export function sumBy<Record_>(records: readonly Record_[], read: (record: Record_) => number): number {
  return records.reduce((total, record) => {
    const value = read(record);
    return Number.isFinite(value) ? total + value : total;
  }, 0);
}

export function uniqueValues<Record_>(
  records: readonly Record_[],
  read: (record: Record_) => string,
): string[] {
  return [...new Set(records.map(read).filter((value) => value !== ""))].sort((a, b) => a.localeCompare(b));
}

