import type { Entity } from "../lib/repository.js";
import { normalizeKey } from "../lib/id.js";
import {
  isNumber,
  maxLength,
  numberRange,
  oneOf,
  required,
  unique,
  validateFields,
  type FieldErrors,
} from "../lib/validation.js";

export const CATEGORIES = ["glaze", "clay", "tools", "other"] as const;
export type Category = (typeof CATEGORIES)[number];

export const CATEGORY_LABELS: Record<Category, string> = {
  glaze: "Glaze",
  clay: "Clay",
  tools: "Tools",
  other: "Other",
};

/** "A couple left" — at or under this count a supply needs attention. */
export const LOW_STOCK_THRESHOLD = 2;

export interface SupplyItem extends Entity {
  name: string;
  supplier: string;
  category: Category;
  quantity: number;
}

export type SupplyInput = Omit<SupplyItem, keyof Entity>;

export type StockStatus = "out" | "low" | "ok";

export function stockStatus(quantity: number): StockStatus {
  if (quantity <= 0) return "out";
  if (quantity <= LOW_STOCK_THRESHOLD) return "low";
  return "ok";
}

export function needsAttention(item: Pick<SupplyItem, "quantity">): boolean {
  return stockStatus(item.quantity) !== "ok";
}

/** Normalised identity of a supply: the same name from the same supplier is a duplicate. */
export function supplyKey(name: string, supplier: string): string {
  return normalizeKey(`${name} from ${supplier}`);
}

export interface SupplyFormValues {
  name: string;
  supplier: string;
  category: string;
  quantity: string;
  /** Computed name+supplier identity, validated for duplicates. */
  key: string;
}

const isWholeNumber = (value: string): string | undefined =>
  value.trim() !== "" && !Number.isInteger(Number(value)) ? "Quantity must be a whole number" : undefined;

export function validateSupply(
  values: SupplyFormValues,
  existingKeys: readonly string[],
): FieldErrors<SupplyFormValues> {
  return validateFields(values, {
    name: [required("Give the supply a name"), maxLength(80, "Keep the name under 80 characters")],
    supplier: [required("Add the supplier"), maxLength(80, "Keep the supplier under 80 characters")],
    category: [oneOf(CATEGORIES, "Choose a type")],
    quantity: [
      required("Enter how many you have left"),
      isNumber("Quantity must be a number"),
      isWholeNumber,
      numberRange(0, 100000, "Quantity must be between 0 and 100,000"),
    ],
    key: [unique(existingKeys, "You already track this item from this supplier")],
  });
}

/** Accepts a stored value only when every field is usable; otherwise the entry is dropped. */
export function parseSupplyRecord(value: unknown): SupplyItem | undefined {
  if (typeof value !== "object" || value === null) return undefined;
  const v = value as Record<string, unknown>;
  if (typeof v.id !== "string" || v.id === "") return undefined;
  if (typeof v.created_at !== "string" || v.created_at === "") return undefined;
  if (typeof v.updated_at !== "string" || v.updated_at === "") return undefined;
  if (typeof v.name !== "string" || v.name.trim() === "") return undefined;
  if (typeof v.supplier !== "string" || v.supplier.trim() === "") return undefined;
  if (typeof v.category !== "string" || !(CATEGORIES as readonly string[]).includes(v.category)) return undefined;
  if (typeof v.quantity !== "number" || !Number.isInteger(v.quantity) || v.quantity < 0) return undefined;
  return {
    id: v.id,
    created_at: v.created_at,
    updated_at: v.updated_at,
    name: v.name.trim(),
    supplier: v.supplier.trim(),
    category: v.category as Category,
    quantity: v.quantity,
  };
}

import { createRepository } from "./repository.js";
import { parseSupplyRecord, type SupplyItem } from "../domain/supply.js";

export const SUPPLY_STORAGE_KEY = "pottery-studio-supplies";

export const supplyRepository = createRepository<SupplyItem>(SUPPLY_STORAGE_KEY, {
  version: 1,
  parseRecord: parseSupplyRecord,
});

import { useState, type FormEvent } from "react";
import { Button, Form, SelectField, TextField } from "../ui/index.js";
import {
  CATEGORIES,
  CATEGORY_LABELS,
  hasErrors,
  supplyKey,
  validateSupply,
  type Category,
  type SupplyInput,
  type SupplyItem,
} from "../domain/supply.js";

interface SupplyFormProps {
  initial?: SupplyItem;
  /** Normalised name+supplier keys already taken (excluding the record being edited). */
  existingKeys: readonly string[];
  submitLabel: string;
  onSubmit: (input: SupplyInput) => void;
  onCancel?: () => void;
}

export function SupplyForm({ initial, existingKeys, submitLabel, onSubmit, onCancel }: SupplyFormProps) {
  const [name, setName] = useState(initial?.name ?? "");
  const [supplier, setSupplier] = useState(initial?.supplier ?? "");
  const [category, setCategory] = useState<string>(initial?.category ?? "glaze");
  const [quantity, setQuantity] = useState(initial ? String(initial.quantity) : "");
  const [errors, setErrors] = useState<ReturnType<typeof validateSupply>>({});

  function handleSubmit(event: FormEvent) {
    event.preventDefault();
    const values = { name, supplier, category, quantity, key: supplyKey(name, supplier) };
    const nextErrors = validateSupply(values, existingKeys);
    setErrors(nextErrors);
    if (hasErrors(nextErrors)) return;
    onSubmit({
      name: name.trim(),
      supplier: supplier.trim(),
      category: category as Category,
      quantity: Number(quantity),
    });
  }

  return (
    <Form onSubmit={handleSubmit}>
      <div className="grid">
        <TextField
          label="Name"
          value={name}
          onChange={(event) => setName(event.target.value)}
          error={errors.name ?? errors.key}
          hint="What it's called, e.g. Cobalt blue"
        />
        <TextField
          label="Supplier"
          value={supplier}
          onChange={(event) => setSupplier(event.target.value)}
          error={errors.supplier}
          hint="Where you get it from"
        />
        <SelectField
          label="Type"
          value={category}
          onChange={(event) => setCategory(event.target.value)}
          options={CATEGORIES.map((value) => ({ value, label: CATEGORY_LABELS[value] }))}
          error={errors.category}
        />
        <TextField
          label="Quantity left"
          value={quantity}
          onChange={(event) => setQuantity(event.target.value)}
          error={errors.quantity}
          hint="How many you have on the shelf"
          inputMode="numeric"
        />
      </div>
      <div className="form__actions">
        <Button type="submit">{submitLabel}</Button>
        {onCancel ? (
          <Button variant="secondary" onClick={onCancel}>
            Cancel
          </Button>
        ) : null}
      </div>
    </Form>
  );
}

import type { ReactNode } from "react";
import { Button, DataTable } from "../ui/index.js";
import { CATEGORY_LABELS, stockStatus, type SupplyItem } from "../domain/supply.js";

interface SupplyTableProps {
  items: readonly SupplyItem[];
  onAdjust: (id: string, delta: number) => void;
  onEdit: (item: SupplyItem) => void;
  onDelete: (item: SupplyItem) => void;
  empty: ReactNode;
}

export function StockBadge({ item }: { item: SupplyItem }) {
  const status = stockStatus(item.quantity);
  if (status === "out") return <span className="stock-badge stock-badge--out">Out of stock</span>;
  if (status === "low") return <span className="stock-badge stock-badge--low">Low</span>;
  return null;
}

export function SupplyTable({ items, onAdjust, onEdit, onDelete, empty }: SupplyTableProps) {
  return (
    <DataTable
      caption="Supplies you're tracking, most urgent first"
      columns={[
        {
          key: "name",
          header: "Supply",
          render: (item) => (
            <div>
              <strong>{item.name}</strong>
              <div className="muted">from {item.supplier}</div>
            </div>
          ),
        },
        {
          key: "category",
          header: "Type",
          render: (item) => CATEGORY_LABELS[item.category],
        },
        {
          key: "quantity",
          header: "Left",
          render: (item) => (
            <div>
              <span>{item.quantity}</span>
              <StockBadge item={item} />
            </div>
          ),
        },
        {
          key: "actions",
          header: "Actions",
          render: (item) => (
            <div className="row-actions">
              <Button
                variant="secondary"
                aria-label={`Use one ${item.name}`}
                disabled={item.quantity === 0}
                onClick={() => onAdjust(item.id, -1)}
              >
                −1
              </Button>
              <Button variant="secondary" aria-label={`Add one ${item.name}`} onClick={() => onAdjust(item.id, 1)}>
                +1
              </Button>
              <Button variant="secondary" aria-label={`Edit ${item.name}`} onClick={() => onEdit(item)}>
                Edit
              </Button>
              <Button variant="danger" aria-label={`Delete ${item.name}`} onClick={() => onDelete(item)}>
                Delete
              </Button>
            </div>
          ),
        },
      ]}
      rows={items}
      empty={empty}
    />
  );
}

import { Button, DataList } from "../ui/index.js";
import { CATEGORY_LABELS, stockStatus, type SupplyItem } from "../domain/supply.js";

interface LowStockPanelProps {
  items: readonly SupplyItem[];
  onEdit: (item: SupplyItem) => void;
}

/** The supplies that need attention: out of stock or down to a couple. */
export function LowStockPanel({ items, onEdit }: LowStockPanelProps) {
  if (items.length === 0) {
    return <p className="muted">Nothing is running low. You're all stocked up.</p>;
  }
  return (
    <DataList
      label="Supplies running low"
      items={items}
      empty={null}
      renderItem={(item) => {
        const status = stockStatus(item.quantity);
        return (
          <>
            <div>
              <strong>{item.name}</strong>{" "}
              <span className="muted">
                from {item.supplier} · {CATEGORY_LABELS[item.category]}
              </span>
              <div>
                {status === "out" ? (
                  <span className="stock-badge stock-badge--out">Out of stock</span>
                ) : (
                  <span className="stock-badge stock-badge--low">{item.quantity} left</span>
                )}
              </div>
            </div>
            <Button variant="secondary" aria-label={`Restock ${item.name}`} onClick={() => onEdit(item)}>
              Restock
            </Button>
          </>
        );
      }}
    />
  );
}

import { useMemo, useState } from "react";
import { useCollection } from "./hooks/useCollection.js";
import { supplyRepository } from "./lib/supplyRepository.js";
import { filterRecords, sortRecords } from "./lib/collection.js";
import {
  CATEGORIES,
  CATEGORY_LABELS,
  LOW_STOCK_THRESHOLD,
  needsAttention,
  stockStatus,
  supplyKey,
  type SupplyInput,
  type SupplyItem,
} from "./domain/supply.js";
import { AppShell, Button, Dialog, EmptyState, Notice, Section, SelectField, StatCard } from "./ui/index.js";
import { SupplyForm } from "./components/SupplyForm.js";
import { SupplyTable } from "./components/SupplyTable.js";
import { LowStockPanel } from "./components/LowStockPanel.js";

/** Out of stock first, then low, then the rest; alphabetical within each band. */
const urgencySortKey = (item: SupplyItem): string => {
  const status = stockStatus(item.quantity);
  const rank = status === "out" ? 0 : status === "low" ? 1 : 2;
  return `${rank}|${item.name.toLowerCase()}`;
};

export function App() {
  const { records, loading, notice, create, update, remove, dismissNotice } = useCollection(supplyRepository);
  const [categoryFilter, setCategoryFilter] = useState("all");
  const [lowOnly, setLowOnly] = useState(false);
  const [editing, setEditing] = useState<SupplyItem | null>(null);
  const [deleting, setDeleting] = useState<SupplyItem | null>(null);

  const lowItems = useMemo(
    () => sortRecords(records.filter(needsAttention), urgencySortKey),
    [records],
  );
  const outCount = useMemo(() => records.filter((item) => stockStatus(item.quantity) === "out").length, [records]);

  const visible = useMemo(
    () =>
      sortRecords(
        filterRecords(records, [
          (item) => categoryFilter === "all" || item.category === categoryFilter,
          (item) => !lowOnly || needsAttention(item),
        ]),
        urgencySortKey,
      ),
    [records, categoryFilter, lowOnly],
  );

  const existingKeys = (excludeId?: string) =>
    records.filter((item) => item.id !== excludeId).map((item) => supplyKey(item.name, item.supplier));

  function handleCreate(input: SupplyInput) {
    create(input);
  }

  function handleEditSubmit(input: SupplyInput) {
    if (editing) update(editing.id, input);
    setEditing(null);
  }

  function handleDeleteConfirm() {
    if (deleting) remove(deleting.id);
    setDeleting(null);
  }

  function handleAdjust(id: string, delta: number) {
    const item = records.find((record) => record.id === id);
    if (item) update(id, { quantity: Math.max(0, item.quantity + delta) });
  }

  const filtersActive = categoryFilter !== "all" || lowOnly;

  return (
    <AppShell
      title="Studio Supplies"
      description="Track your glazes, clay and tools, and spot what's running low before it runs out."
    >
      {notice ? (
        <Notice tone="warning" onDismiss={dismissNotice}>
          {notice}
        </Notice>
      ) : null}

      <div className="grid">
        <StatCard label="Supplies tracked" value={records.length} />
        <StatCard label="Running low" value={lowItems.length} />
        <StatCard label="Out of stock" value={outCount} />
      </div>

      <Section title={`Running low (at or under ${LOW_STOCK_THRESHOLD} left)`}>
        <LowStockPanel items={lowItems} onEdit={setEditing} />
      </Section>

      <Section title="Add a supply">
        <SupplyForm existingKeys={existingKeys()} submitLabel="Add supply" onSubmit={handleCreate} />
      </Section>

      <Section
        title="All supplies"
        actions={
          <div className="filters">
            <SelectField
              label="Filter by type"
              value={categoryFilter}
              onChange={(event) => setCategoryFilter(event.target.value)}
              options={[
                { value: "all", label: "All types" },
                ...CATEGORIES.map((value) => ({ value, label: CATEGORY_LABELS[value] })),
              ]}
            />
            <label className="filter-toggle">
              <input type="checkbox" checked={lowOnly} onChange={(event) => setLowOnly(event.target.checked)} />
              Low stock only
            </label>
          </div>
        }
      >
        {loading ? (
          <p className="muted">Loading your supplies…</p>
        ) : visible.length === 0 ? (
          records.length === 0 ? (
            <EmptyState
              title="No supplies yet"
              description="Add your first glaze, clay or tool above and it will show up here."
            />
          ) : (
            <EmptyState
              title="Nothing matches these filters"
              description="No supplies match the current type and stock filters."
              action={
                <Button
                  variant="secondary"
                  onClick={() => {
                    setCategoryFilter("all");
                    setLowOnly(false);
                  }}
                >
                  Clear filters
                </Button>
              }
            />
          )
        ) : (
          <SupplyTable
            items={visible}
            onAdjust={handleAdjust}
            onEdit={setEditing}
            onDelete={setDeleting}
            empty={null}
          />
        )}
      </Section>

      <Dialog open={editing !== null} title={editing ? `Edit ${editing.name}` : "Edit supply"} onClose={() => setEditing(null)}>
        {editing ? (
          <SupplyForm
            key={editing.id}
            initial={editing}
            existingKeys={existingKeys(editing.id)}
            submitLabel="Save changes"
            onSubmit={handleEditSubmit}
            onCancel={() => setEditing(null)}
          />
        ) : null}
      </Dialog>

      <Dialog open={deleting !== null} title="Delete supply" onClose={() => setDeleting(null)}>
        <p>
          {deleting ? (
            <>
              Remove <strong>{deleting.name}</strong> from {deleting.supplier}? You won't be able to bring it back.
            </>
          ) : null}
        </p>
        <div className="form__actions">
          <Button variant="secondary" onClick={() => setDeleting(null)}>
            Cancel
          </Button>
          <Button variant="danger" onClick={handleDeleteConfirm}>
            Delete
          </Button>
        </div>
      </Dialog>
    </AppShell>
  );
}

